 3 /// Sum of price * quantity for every line item.
 4 pub fn subtotal(items: &[(f64, u32)]) -> f64 {
 5     items.iter().map(|(price, _quantity)| *price).sum()
 6 }
 7 
 8 /// Apply a percentage discount, never letting the result go below zero.
 9 pub fn apply_discount(total: f64, percent: f64) -> f64 {
